// HelloEngineer.java
// Purpose: Introduction to Java program structure
// Author: [Your Name Here]
// Date: 23-Feb-2026

public class HelloEngineer {

    /**
     * main() is the entry point of every Java application.
     * JVM (Java Virtual Machine) looks for this EXACT signature to start execution.
     * 
     * @param args command-line arguments (we'll use these later in the course)
     */
    public static void main(String[] args) {
        // System.out.println prints text and moves to a new line
        System.out.println("Hello from RoboBank Tech Team!");
        System.out.println("I am: [YOUR NAME]");
        System.out.println("Based in: [YOUR CITY]");

        // System.out.printf is for formatted output (like printf in C)
        System.out.printf("Java version I'm using: %s%n",
                          System.getProperty("java.version"));

        // Demonstrate what you know about the Java platform:
        System.out.println("\n--- Java Platform Architecture ---");
        System.out.println("JDK  = JRE + Development Tools (javac, javadoc, jar)");
        System.out.println("JRE  = JVM + Standard Class Libraries");
        System.out.println("JVM  = Executes .class bytecode | Platform-specific");
        System.out.println("WORA = Write Once, Run Anywhere!");
    }
}
